def summarize_orders(orders):
    from datetime import datetime
    monthly_totals = {}
    for order in orders:
        if datetime.strptime(order["date"], "%Y-%m-%d") >= datetime(2024, 1, 1):
            month_key = order["date"][:7]
            monthly_totals[month_key] = monthly_totals.get(month_key, 0) + order["amount"]
    return monthly_totals

This function filters orders by date, groups the remaining orders by month, and calculates the total amount for each month.
